<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, reactive, ref } from 'vue'
import { studentAPI } from '../../api/student'
import type { ApiKey, Model, Organization, Project, RequestedModel } from '../../api/types'
import { APIError } from '../../api/client'
import StatusProgress from '../../components/StatusProgress.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import AppDialog from '../../components/AppDialog.vue'
import ModelForm, { type ModelFormValue } from '../../components/ModelForm.vue'
import LoadingRegion from '../../components/LoadingRegion.vue'
import { useLoadState } from '../../composables/useLoadState'
import { useToast } from '../../composables/useToast'
import { changedApiKeyID } from '../../utils/keyStatusEvents'

const orgs = ref<Organization[]>([]), projects = ref<Project[]>([]), models = ref<Model[]>([]), keys = ref<ApiKey[]>([])
const detail = ref<ApiKey | null>(null), secret = ref(''), copied = ref(false), claimConfirm = ref<ApiKey | null>(null), modelDialog = ref(false), error = ref('')
const toast = useToast(), loadState = useLoadState(), modelQuery = ref('')
const form = reactive({ organization_id: '', project_id: '', model_ids: [] as string[], requested_models: [] as RequestedModel[], name: '' })
const custom = reactive<ModelFormValue>({ model_id: '', display_name: '', description: null, category: 'text', capabilities: [], input_modalities: [], output_modalities: [], context_window: null, max_output_tokens: null, is_common: false, status: 'pending_configuration' })
const allCount = computed(() => form.model_ids.length + form.requested_models.length)
const filteredModels = computed(() => models.value.filter(model => !modelQuery.value || `${model.display_name} ${model.model_id} ${model.capabilities.join(' ')}`.toLowerCase().includes(modelQuery.value.toLowerCase())))
const canSubmit = computed(() => Boolean(form.organization_id && form.project_id && form.name.trim() && allCount.value > 0 && allCount.value <= 100))

async function load() { await loadState.run(async () => { try { [orgs.value, models.value, keys.value] = await Promise.all([studentAPI.organizations(), studentAPI.models(), studentAPI.keys()]); error.value = '' } catch (caught) { error.value = msg(caught) } }) }
async function chooseOrg() { if ((form.model_ids.length || form.requested_models.length) && !confirm('切换组织将清空项目、已选模型和新模型草稿，是否继续？')) return; form.project_id = ''; form.model_ids = []; form.requested_models = []; await loadState.run(async () => { projects.value = form.organization_id ? await studentAPI.projects(form.organization_id) : [] }) }
function toggleModel(model: Model) { const key = model.model_id.toLowerCase(), index = form.model_ids.findIndex(value => value.toLowerCase() === key); if (index >= 0) form.model_ids.splice(index, 1); else if (allCount.value < 100) form.model_ids.push(model.model_id) }
function resetCustom() { Object.assign(custom, { model_id: '', display_name: '', description: null, category: 'text', capabilities: [], input_modalities: [], output_modalities: [], context_window: null, max_output_tokens: null, is_common: false, status: 'pending_configuration' }); modelQuery.value = '' }
function acceptModel() { error.value = ''; if (!custom.model_id.trim() || !custom.display_name.trim() || !custom.capabilities.length || !custom.input_modalities.length || !custom.output_modalities.length) { error.value = '请完整填写模型 ID、显示名称、能力和输入/输出模态'; return }; const key = custom.model_id.trim().toLowerCase(); if (form.model_ids.some(value => value.toLowerCase() === key) || form.requested_models.some(value => value.model_id.toLowerCase() === key)) { error.value = '该模型已在当前白名单中'; return }; if (allCount.value >= 100) { error.value = '模型白名单最多添加 100 个模型'; return }; const existing = models.value.find(model => model.model_id.toLowerCase() === key); if (existing) { form.model_ids.push(existing.model_id); toast.success('已加入平台已有模型') } else { form.requested_models.push({ model_id: custom.model_id.trim(), display_name: custom.display_name.trim(), description: custom.description, category: custom.category, capabilities: [...custom.capabilities], input_modalities: [...custom.input_modalities], output_modalities: [...custom.output_modalities], context_window: custom.context_window, max_output_tokens: custom.max_output_tokens }); toast.success('新模型已加入申请') }; modelDialog.value = false; resetCustom() }
async function submit() { if (!canSubmit.value) return; error.value = ''; try { await studentAPI.submit({ ...form }); Object.assign(form, { organization_id: '', project_id: '', model_ids: [], requested_models: [], name: '' }); projects.value = []; await load(); toast.success('密钥申请已提交') } catch (caught) { error.value = msg(caught) } }
async function show(id: string) { try { detail.value = await studentAPI.key(id); secret.value = ''; copied.value = false } catch (caught) { error.value = msg(caught) } }
async function handleRefresh(event: Event) { const payload = (event as CustomEvent).detail, changedID = payload?.event === 'api_key.status_changed' ? changedApiKeyID(keys.value, payload.data) : null; await load(); if (changedID) await show(changedID) }
async function claim() { if (!claimConfirm.value) return; try { const result = await studentAPI.claim(claimConfirm.value.id); secret.value = result.api_key; detail.value = claimConfirm.value; claimConfirm.value = null; await load(); toast.success('密钥已领取并激活') } catch (caught) { error.value = msg(caught) } }
async function copy() { try { await navigator.clipboard.writeText(secret.value); copied.value = true; toast.success('已复制密钥') } catch { toast.error('复制失败，请手动复制') } }
function closeSecret() { if (secret.value && !copied.value && !confirm('密钥尚未复制，关闭后无法再次查看。确定关闭？')) return; secret.value = ''; copied.value = false; detail.value = null }
function msg(caught: unknown) { return caught instanceof APIError ? caught.message : '请求失败，请稍后重试' }
onMounted(() => { void load(); window.addEventListener('nebula:refresh', handleRefresh) })
onBeforeUnmount(() => window.removeEventListener('nebula:refresh', handleRefresh))
</script>
<template><section class="page"><div class="page-heading"><div><p class="eyebrow">STUDENT</p><h1>申请密钥</h1><p class="muted">按组织、项目、模型与 Key 名称完成申请。</p></div><button class="button secondary" @click="load">刷新</button></div><p v-if="error" class="error banner">{{ error }}</p><LoadingRegion :initial-loading="loadState.initialLoading.value" :refreshing="loadState.refreshing.value" variant="split" label="正在加载组织、模型和申请"><div class="grid two"><section class="panel"><h2>新申请</h2><form @submit.prevent="submit"><label>1. 组织<select v-model="form.organization_id" @change="chooseOrg"><option value="">请选择组织</option><option v-for="org in orgs" :key="org.id" :value="org.id">{{ org.name }}</option></select></label><label>2. 项目<select v-model="form.project_id" :disabled="!form.organization_id"><option value="">请选择项目</option><option v-for="project in projects" :key="project.id" :value="project.id" :disabled="project.status !== 'active' || !project.has_mentor">{{ project.name }}{{ project.status !== 'active' ? '（已停用）' : !project.has_mentor ? '（暂无负责导师）' : '' }}</option></select></label><fieldset :disabled="!form.project_id"><legend>3. 模型白名单（{{ allCount }}/100）</legend><input v-model="modelQuery" placeholder="搜索可见模型"/><div v-for="model in filteredModels" :key="model.id" class="list-row"><div><strong>{{ model.display_name }}</strong><p class="muted">{{ model.model_id }}{{ model.status === 'inactive' ? ' · 需老师重新配置后才能终审' : '' }}</p></div><button type="button" class="button" :class="form.model_ids.some(value => value.toLowerCase() === model.model_id.toLowerCase()) ? 'secondary' : 'ghost'" @click="toggleModel(model)">{{ form.model_ids.some(value => value.toLowerCase() === model.model_id.toLowerCase()) ? '已选择' : '选择' }}</button></div><div class="chip-list"><span v-for="model in form.requested_models" :key="model.model_id" class="chip">{{ model.display_name }} · 新模型 <button type="button" class="icon-button" @click="form.requested_models = form.requested_models.filter(value => value !== model)">×</button></span></div><button type="button" class="button secondary" @click="modelDialog = true; resetCustom()">申请新模型</button></fieldset><label>4. Key 名称<input v-model="form.name" maxlength="128" placeholder="例如 research-key"/></label><button class="button primary wide" :disabled="!canSubmit || loadState.loading.value">提交申请</button></form></section><section class="panel"><div class="panel-heading"><h2>我的申请</h2><span>{{ keys.length }}</span></div><article v-for="key in keys" :key="key.id" class="key-card"><div class="row"><div><strong>{{ key.name }}</strong><p class="muted">{{ key.organization.name }} · {{ key.project.name }} · {{ key.models.length }} 个模型</p></div><StatusBadge :status="key.status"/></div><StatusProgress :current="key.progress.current" :completed="key.progress.completed_steps"/><div class="actions"><button class="button ghost" @click="show(key.id)">审核状态</button><button v-if="key.status === 'approved'" class="button primary" @click="claimConfirm = key">一次性领取</button></div></article></section></div></LoadingRegion><AppDialog :open="modelDialog" title="申请新模型" @update:open="modelDialog = $event"><ModelForm :model="custom" :show-common="false" submit-label="加入白名单" @submit="acceptModel"/></AppDialog><AppDialog :open="Boolean(claimConfirm)" title="确认一次性领取" @update:open="claimConfirm = $event ? claimConfirm : null"><p>完整 API Key 仅显示一次。领取后立即转为 ACTIVE。</p><div class="actions"><button class="button primary" @click="claim">确认领取</button></div></AppDialog><AppDialog :open="Boolean(detail)" :title="secret ? '立即保存 API Key' : '申请详情'" @update:open="secret ? closeSecret() : detail = null"><template v-if="secret"><p class="secret">{{ secret }}</p><button class="button secondary" @click="copy">{{ copied ? '已复制' : '复制密钥' }}</button></template><template v-else-if="detail"><StatusProgress :current="detail.progress.current" :completed="detail.progress.completed_steps"/><p>{{ detail.organization.name }} · {{ detail.project.name }}</p><p>{{ detail.models.map(model => model.model_id).join('、') }}</p><div v-for="audit in detail.audits" :key="audit.created_at" class="list-row"><span>{{ audit.actor_role }} · {{ audit.action }}</span><span>{{ audit.comment || '无意见' }}</span></div></template></AppDialog></section></template>
